                            invariant(false, "Unknown unit of work tag (%s). This error is likely caused by a bug in React. Please file an issue.", (tostring(subtreeFlags)))
                        end
                    end
                end
            end

            return nil
        end

        bubbleProperties(p35)

        return nil
    end
}
